window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-rastreamento-do-cancer-de-mama"]={"block":"anki:ginecologia-rastreamento-do-cancer-de-mama","label":"Anki · Rastreamento do Câncer de Mama","count":100,"questions":[{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-ad966896ec058bb5","number":"0201m","sourceNumber":"0201m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Sobre os exames de mamas:","options":{"A":"A sensibilidade da ressonância magnética das mamas é maior do que o da mamografia, porém a especificidade é menor.","B":"A dopplerfluxometria das mamas tem como vantagem a sensibilidade maior que a ultrassonografia e ter boa reprodutibilidade.","C":"A ultrassonografia das mamas tem achados comparáveis com a mamografia com a vantagem de não ter radioexposição.","D":"A mamografia tem baixo custo e boa acurácia, porém depende da densidade mamária para boa interpretação.","E":"O melhor exame para avaliação de nódulos palpáveis é a ressonância magnética das mamas, por não ter radioexposição."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947621","ankiGuid":"gPMFT=Bj{2"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-e8dcaa3d25201018","number":"0202m","sourceNumber":"0202m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Sobre as formas de rastreamento do câncer de mama, é correto afirmar que:","options":{"A":"O Autoexame Mensal da Mama (AEM) ainda é recomendado. Apesar das poucas evidências, o AEM demonstrou melhorar a sobrevida das pacientes.","B":"A maioria dos grupos de especialistas recomenda a tomada de decisão compartilhada em relação à triagem com mamografia para as mulheres na faixa etária de 40 a 49 anos.","C":"A ressonância magnética da mama deve ser anual, a partir dos 50 anos, para mulheres com BRCA positivo.","D":"Tomografia por emissão de pósitrons e Ki-67, um marcador tumoral sérico, são formas promissoras para o rastreamento do câncer de mama."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947622","ankiGuid":"C7I6)XdhIY"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-95af8b4db5c5d985","number":"0203m","sourceNumber":"0203m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 42 anos de idade, assintomática retorna ao ambulatório com resultado de mamografia (4 incidências básicas): BI- RADS 0, mamas lipossubstituídas e microcalcificações agrupadas em área de 8mm). Qual é o complemento de imagem que deve ser solicitado?","options":{"A":"Ampliação.","B":"Compressão.","C":"Ultrassom.","D":"Ressonância magnética."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947623","ankiGuid":"o-`wL!Ym6D"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-c63dee62872ba92d","number":"0204m","sourceNumber":"0204m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O câncer de mama ainda se caracteriza como o câncer ginecológico mais prevalente em todo mundo. Assim sendo, a propedêutica é fundamental para o tratamento precoce. Assinale a alternativa que contém o método de maior sensibilidade para o rastreamento do câncer de mamas.","options":{"A":"Ressonância magnética.","B":"Mamografia.","C":"Ultrassonografia mamária.","D":"Auto-exame das mamas.","E":"Exame clínico realizado por especialista."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947624","ankiGuid":"ys2/^z7SzU"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d7b32c83e848cc4c","number":"0205m","sourceNumber":"0205m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Idosa de 76 anos comparece à consulta, solicitando informações de quando deve realizar nova mamografia. A última foi há dois anos. Deve-se explicar que nessa faixa etária, em relação ao rastreamento para câncer de mama, a recomendação do Ministério da Saúde é de:","options":{"A":"aumentar o intervalo de rastreamento","B":"fazer rastreamento por ressonância","C":"oferecer rastreamento opcional","D":"interromper o rastreamento"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947625","ankiGuid":"b4^6!E@z2N"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-aaaba0d86ab2a18a","number":"0206m","sourceNumber":"0206m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Os métodos existentes para a detecção precoce do câncer de mama não reduzem a incidência, mas podem reduzir a mortalidade pela doença. Nesse sentido, o Ministério da Saúde preconiza que, na população de risco padrão para o câncer de mama, o rastreio seja realizado pela mamografia,","options":{"A":"em intervalos bianuais, em mulheres entre 50 e 69 anos.","B":"em intervalos anuais, em mulheres entre 40 e 69 anos.","C":"em grupo familiar menor que 40 anos, com antecedente positivo para o câncer de mama, em mulheres com idade menor que 40 anos.","D":"em meio familiar, com antecedente familiar positivo para o câncer de mama, em mulheres com idade superior a 70 anos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947626","ankiGuid":"QSxfD{sbrM"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d8695163ef30cf0f","number":"0207m","sourceNumber":"0207m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O American College of Radiology recomendou o Breast Imaging Reporting and Data System (BI- -RADS) como esquema padrão para a descrição de lesões mamográficas. Qual é o BI-RADS numa paciente com achado suspeito e que deve ser considerada a biópsia?","options":{"A":"1.","B":"2.","C":"3.","D":"4.","E":"0."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947627","ankiGuid":"v<}~vD6nID"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-c499a0e8a6a70948","number":"0208m","sourceNumber":"0208m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O câncer de mama é, na atualidade, uma questão de saúde pública mundial. O rastreamento deve contemplar populações de risco padrão para desenvolvimento do câncer de mama, chamado risco populacional. Quanto ao rastreamento do câncer de mama, analise as afirmações abaixo.\n\nDas afirmações, estão corretas:","options":{"A":"I, II e IV.","B":"II, III e IV.","C":"I, III e IV.","D":"I, II e III."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-mama/paste-b443cc96292016610b773d6c734680f84776de0d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947628","ankiGuid":"BR9ANI/;$c"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d63f4c77836632cd","number":"0209m","sourceNumber":"0209m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O diagnóstico precoce do câncer de mama faz com que o tratamento seja feito na fase inicial da doença, melhorando sobremaneira o prognóstico. Segundo a Federação Brasileira de Ginecologia e Obstetrícia (FEBRASGO) e a Sociedade Brasileira de Mastologia (SBM), esse rastreamento deve ser feito","options":{"A":"em todas as mulheres, com mamografia a partir de quarenta anos de idade, associada à dosagem sérica do CA 15.3.","B":"por meio de mamografia com cintilografia (mamocintilografia), a partir de quarenta anos de idade.","C":"por meio de ressonância magnética das mamas a partir de quarenta anos de idade, porém seu resultado é alterado se as mamas forem densas.","D":"por meio de mamografia anual, a partir de quarenta anos de idade, em paciente de baixo risco.","E":"por meio de tomografia de superfície, a partir de quarenta anos de idade."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947629","ankiGuid":"CKcr[@p+35"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-4b5856099ca65ed2","number":"0210m","sourceNumber":"0210m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Uma mulher de 40 anos com histórico familiar de câncer de mama materno (mãe teve câncer aos 70 anos) realiza mamografia de rastreio. 0 laudo da mamografia foi BI-RADS 2. Segundo as orientações do Ministério da Saúde acerca da realização e resultado do exame, é correto afirmar que:","options":{"A":"Foi realizado no momento correto / Requer realização de Core biopsy;","B":"Foi realizado de forma precoce / Deve-se complementar com ultrassonografia;.","C":"Não seguiu as orientações do Ministério da Saúde / Complementar com ressonância;","D":"Seguiu as orientações do Ministério da Saúde / Repetir o exame em seis meses;","E":"Não seguiu as orientações do Ministério da Saúde / Repetir o exame aos 50 anos."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947630","ankiGuid":"n~%@`EMq?O"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-0d7e7a5ec8151509","number":"0211m","sourceNumber":"0211m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Segundo a Organização Mundial da Saúde, o climatério compreende o período de vida da mulher entre o final da fase reprodutiva e a senilidade. Em geral, varia dos 40 aos 65 anos. Nesse período, ocorre a menopausa, definida como a interrupção permanente da menstruação após 12 meses de amenorreia. Sobre o climatério, sabe-se que:","options":{"A":"o diagnóstico deve ser confirmado com as dosagens de prolactina e LH.","B":"os fogachos são sensações transitórias súbitas de calor que se iniciam nos pés e sobem em direção às pernas e joelhos.","C":"dentre os exames complementares para sua propedêutica, a RNM de tórax e cintilografia óssea são mandatórias.","D":"a mamografia e a colpocitologia oncoparasitária são fundamentais na propedêutica básica do climatério."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947631","ankiGuid":"GlKq;c,>es"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-e148f681ef4126bd","number":"0212m","sourceNumber":"0212m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 52 anos de idade, realizou mamografia de rotina que identificou grupo de microcalcificações pleomórficas, com extensão de 0,7 cm, localizadas em quadrante superolateral de mama direita. Qual é a melhor estratégia para o diagnóstico histopatológico?","options":{"A":"Biópsia por agulha grossa (core biopsy) guiada por mamografia.","B":"Biópsia assistida a vácuo (mamotomia) guiada por ultrassonografia.","C":"Biópsia por agulha grossa (core biopsy) guiada por ultrassonografia.","D":"Biópsia assistida a vácuo (mamotomia) guiada por mamografia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947632","ankiGuid":"v^5bSu?3af"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-8935d16b78a722ec","number":"0213m","sourceNumber":"0213m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Em uma mamografia classificada como categoria 3 ( BI-RADS ) , qual a conduta a ser seguida?","options":{"A":"Controle anual.","B":"Biópsia cirúrgica.","C":"Controle trimestral.","D":"Controle semestral.","E":"Biópsia percutânea."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947633","ankiGuid":"k~`>V}{j-A"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-7cb0e80c62a5a363","number":"0214m","sourceNumber":"0214m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 35 anos, sem histórico familiar de câncer de mama ou ginecológico, sem queixas mamárias, comparece ao consultório, pois está com medo de ter câncer de mama após ter visto reportagem sobre o caso “Angelina Jolie”. Exame físico: mamas normais. De acordo com as recomendações publicadas pela FEBRASGO e pela Sociedade Brasileira de Mastologia de 2017, a conduta mais adequada é:","options":{"A":"realizar apenas US de mamas nesse momento e mamografia anual após os 40 anos","B":"apesar da paciente estar assintomática, iniciar rastreio mamográfico anual imediatamente","C":"realizar mamografia anual a partir dos 40 anos e complementar com US apenas se necessário","D":"iniciar rastreio anual com mamografia nesse momento e US de mamas a partir dos 40 anos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947634","ankiGuid":"lk#?(Y/4)/"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-b682b5f6a5a9cf10","number":"0215m","sourceNumber":"0215m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Em mamografia diagnóstica, mulher de 66 anos apresenta linfoadenopatia (LAP) regional unilateral. A paciente relata aplicação de vacina Pfizer-BioNTech contra Covid-19 na semana anterior. Neste caso,","options":{"A":"não há estudos mostrando correlação entre vacinação contra Covid-19 e aparecimento de LAP.","B":"a LAP tem pouco valor diagnóstico no câncer de mama e, portanto, está associada à vacinação contra Covid-19.","C":"a LAP pode ser relacionada à vacina, se for ipsilateral à aplicação, mas deve-se seguir investigação de caso suspeito de câncer de mama.","D":"a LAP está, frequentemente associada sempre ao câncer de mama e é necessário realizar biópsia para esclarecimento diagnóstico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947635","ankiGuid":"dAnc6j[<1W"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-7fe30c66df03d0b6","number":"0216m","sourceNumber":"0216m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 58 anos realizou mamografia de rastreamento, com laudo BI-RADS 5, evidenciando nódulo espiculado de limites imprecisos de aproximadamente 2cm. Ao exame, apresenta nódulo endurecido com retração do complexo areolopapilar. A conduta proposta é a realização de:","options":{"A":"ressonância nuclear magnética","B":"biópsia por agulha grossa","C":"tumorectomia","D":"mastectomia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947636","ankiGuid":"i4K^tf[>A5"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-868f7047130d7aa5","number":"0217m","sourceNumber":"0217m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente, 35 anos, realizou biopsia mamária de nódulo compatível com hiperplasia ductal atípica. Não sabe referir história familiar pois foi adotada na infância. Procura ginecologista para realizar exames para prevenção do câncer de mama. Assinale a assertiva correta quanto à classificação de risco da paciente e adequada estratégia de rastreamento com as recomendações do Colégio Brasileiro de Radiologia e da Federação Brasileira de Ginecologia e Obstetrícia (Febrasgo).","options":{"A":"Risco intermediário: realizar mamografia anual + Ultrassonografia (USG) pode ser solicitada de maneira individualizada.","B":"Risco intermediário: realizar mamografia anual + Ultrassonografia e ressonância magnética complementares.","C":"Alto Risco: realizar mamografia anual + Ultrassonografia e ressonância magnética complementares.","D":"Alto Risco: Mamografia e ressonância magnética anuais a partir dos 30 anos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947637","ankiGuid":"J)7CY0pjj{"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-55eced46c51d537a","number":"0218m","sourceNumber":"0218m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Parte do programa de rastreamento de câncer de mama é identificar mulheres com maior chance de desenvolver a doença. Pessoas com risco vitalício maior ou igual a 20% (RR > 2,5) são consideradas de alto risco. Considerando apenas parentes de primeiro grau, qual dos seguintes antecedentes familiares aumenta o risco relativo para câncer de mama?","options":{"A":"Carcinoma espinocelular de colo uterino.","B":"Adenocarcinoma de pulmão.","C":"Carcinoma papilífero de tireoide.","D":"Carcinoma neuroendocrino de pâncreas.","E":"Adenocarcinoma de ovário."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947638","ankiGuid":"zVLLE)hh,P"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d659810b4d709b2f","number":"0219m","sourceNumber":"0219m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O Breast Image Reporting and Data System (BIRADS) auxilia na padronização e divide os achados em categorias. A categoria que se refere a achados provavelmente benignos é:","options":{"A":"0.","B":"1.","C":"2.","D":"3.","E":"6."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947639","ankiGuid":"ti&uz,*nuc"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-308551cde6cb98a6","number":"0220m","sourceNumber":"0220m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Devido à sua prevalência, o câncer de mama determina um grande empenho da comunidade científica em definir as melhores condições de rastreamento e detecção da doença. A mamografia exerce um papel fundamental na detecção precoce do câncer de mama, cuja incidências mínimas preconizadas são:","options":{"A":"Póstero-anterior (PA) e perfil.","B":"Crânio-caudal (CC) e médio lateral oblíqua (MLO).","C":"Elkund.","D":"Magnificação e compressão focal.","E":"Crânio-caudal (CC) e perfil."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947640","ankiGuid":"BBaQ][$2jR"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-a08dc67395b035d2","number":"0221m","sourceNumber":"0221m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Segundo a Febrasgo, nas mulheres sem fatores de risco, a mamografia, com propósito de detectar lesões precursoras do câncer de mama ou câncer de mama em estádios iniciais, deve ser realizada","options":{"A":"anualmente, dos quarenta aos 49 anos de idade, e, a cada dois anos, dos cinquenta aos 74 anos de idade.","B":"anualmente, dos 45 aos 54 anos de idade, e, a cada dois anos, a partir dos 55 anos de idade.","C":"anualmente, dos quarenta aos setenta anos de idade.","D":"a cada dois anos, dos cinquenta aos 74 anos de idade.","E":"a cada três anos, dos cinquenta aos 69 anos de idade."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947641","ankiGuid":"dt)I71TE~i"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-808b45480db7de7b","number":"0222m","sourceNumber":"0222m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"De acordo com as diretrizes do Ministério da Saúde/INCA para a detecção precoce do câncer de mama no Brasil, pode- se afirmar que","options":{"A":"alterações no formato do mamilo e retração de pele devem ser acompanhadas por ultrassonografia mamária.","B":"a mamografia é o exame de rastreio do câncer de mama e deve ser realizada anualmente entre 45 e 65 anos, no intuito de identificar a doença em fase assintomática.","C":"nódulos mamários em mulheres acima de 50 anos devem ser referenciados para serviço de diagnóstico.","D":"os métodos existentes para a detecção precoce do câncer de mama reduzem a incidência e a mortalidade pela doença.","E":"a ultrassonografia é utilizada na diferenciação de cistos e nódulos sólidos na mama, na avaliação de nódulos palpáveis e é considerada método de rastreio para detecção precoce de câncer de mama em qualquer faixa etária."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947642","ankiGuid":"Ac?=`]}i-J"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-270c464ea23c0253","number":"0223m","sourceNumber":"0223m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 61 anos, sem queixas ginecológicas, comparece à Unidade Básica de Saúde para trazer resultado da mamografia realizada em agosto de 2020 e que pode ser vista abaixo. No exame clínico das mamas não havia nódulos palpáveis. Menopausa aos 52 anos, G4P3A 1 e nega uso de terapia hormonal.\n\nQual a conduta MAIS ADEQUADA para essa paciente após avaliar a mamografia?","options":{"A":"Encaminhar para realização de biópsia e estudo histopatológico da mama direita","B":"Encaminhar para punção aspirativa por agulha fina na mama esquerda","C":"Solicitar ampliação de imagem da mama esquerda devido à calcificação presente","D":"Solicitar ultrassonografia das mamas e axilas para complementar a propedêutica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-mama/paste-227b0aa506d9c19c7300e390f5902d13eb5f449b.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947643","ankiGuid":"C[0Hc764NP"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-a3233f5c19ca94fd","number":"0224m","sourceNumber":"0224m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher com 43 anos, G2P2, em consulta na Unidade de Saúde da Família, informa estar bem e que veio apenas pegar pedido para realizar um exame de mamografia para rastreamento do câncer de mama. Nega quaisquer antecedentes pessoais e familiares de alterações mamárias benignas ou malignas. Informa ter engravidado aos 27 e aos 30 anos e ter amamentado seus filhos por 15 meses cada um. Nega uso de qualquer medicação no momento ou no passado. O exame clínico das mamas é normal. Como você orientaria esta mulher de acordo com as diretrizes do SUS?","options":{"A":"Forneceria os pedidos de mamografia seguindo a estratégia breast awareness (consciência da mama), uma vez que a mulher demonstra estar consciente para a saúde das mamas.","B":"Forneceria o pedido de mamografia, considerando o rastreamento oportunístico, que oferece o exame a quem busca a unidade de saúde.","C":"Orientaria que, neste momento, o rastreamento mamográfico não estaria indicado para sua faixa etária e seu perfil.","D":"Orientaria que com 45 anos seria ofertado o rastreamento na modalidade organizado que convida formalmente as mulheres para o rastreamento."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947644","ankiGuid":"p;WWYo@BG/"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-42248b493b23abf9","number":"0225m","sourceNumber":"0225m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 51 anos, nulípara, menopausa há 1 ano, retorna à consulta na unidade básica de saúde para checar mamografia de rastreamento. Tem como antecedente uma tia avó com história de câncer de mama e fez uso de contraceptivo hormonal combinado por 20 anos. Há um ano retirou o sistema intrauterino de levonorgestrel que vinha usando como método contraceptivo nos últimos 5 anos. Não apresenta alteração detectável no exame físico. O laudo da mamografia vem descrito como B1-RADS® 3 e apresenta a imagem abaixo.\n\nConsiderando a história clínica e a imagem, assinale a alternativa que contenha a conduta mais adequada, segundo orientações do Ministério da Saúde.","options":{"A":"Manter seguimento rotineiro com mamografia anual.","B":"Solicitar ultrassonografia mamária complementar.","C":"Encaminhar para realização de análise histopatológica.","D":"Realizar nova mamografia em seis meses."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-mama/paste-109a6fd49302ee261f6c7bb3b6a0f48c33c189b6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947645","ankiGuid":"z^lXHdyqy>"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-f3139c61aa21add2","number":"0226m","sourceNumber":"0226m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 40 anos relata que sua mãe teve câncer de mama aos 72 anos. Realiza mamografia e procura o médico de família para orientação. O resultado da mamografia foi BI-RADS 1. Quanto à realização e o resultado da mamografia, respectivamente, é correto afirmar que:","options":{"A":"não seguiu as recomendações do Ministério da Saúde / normal","B":"seguiu as recomendações do Ministério da Saúde / inconclusivo","C":"seguiu as recomendações do Ministério da Saúde / indeterminado","D":"não seguiu as recomendações do Ministério da Saúde / mostra alterações benignas"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947646","ankiGuid":"i~zaTvx*#m"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-596627501bc20ae0","number":"0227m","sourceNumber":"0227m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"A categoria 3 da classificação BI-RADS® (Breast Image Reporting and Data System), desenvolvida pelo American College of Radiology, é definida por:","options":{"A":"“Anormalidade suspeita”: probabilidade intermediária de câncer, entre 3% e 94%, o que justifica a estratificação das lesões em baixo, intermediário ou alto grau de suspeição.","B":"“Achados provavelmente benignos”: apresentam risco de malignidade inferior a 2%.","C":"“Incompleta”: necessária avaliação complementar dos achados por outro método de imagem ou por incidências especiais na mamografia.","D":"“Achados benignos”: nenhuma característica sugestiva de malignidade.","E":"“Altamente sugestivo de malignidade”: a probabilidade de malignidade é superior à 95%, e a indicação é de estudo anatomopatológico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947647","ankiGuid":"dIIYoK=+[!"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-031c256476e4a3ff","number":"0228m","sourceNumber":"0228m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O termo BI-RADS é uma sistematização internacional para a avaliação mamária, interpretação do exame e confecção dos laudos de exames de imagem especificamente da mama. Uma paciente de 51 anos de idade apresenta laudo mamográfico de assimetria focal à direita, palpável no exame físico mamário. Considera-se tal achado como BI-RADS de categoria","options":{"A":"2.","B":"3.","C":"4.","D":"5."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947648","ankiGuid":"LZy$HzAnrw"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-cb07c85c866e99b5","number":"0229m","sourceNumber":"0229m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 50 anos procura o consultório médico com queixa de nódulo palpável em mama direita há 1 mês. Relata que sua tia materna teve histórico de câncer de mama aos 60 anos. Ao exame físico, apresenta nódulo em mama direita, no quadrante inferomedial, regular, fibroelástico, móvel aos planos profundos, medindo 2,5 cm. Realizou mamografia com achado de nódulo isodenso em mama direita, medindo 2,5 cm, BIRADS 0. Realizada uma ultrassonografia mamária, ficou comprovado tratar-se de um nódulo classificado como BIRADS 2. O achado que corresponde ao BIRADS 2 ultrassonográfico é","options":{"A":"cisto oval, com conteúdo espesso.","B":"nódulo hipoecoico, circunscrito.","C":"cisto oval, com conteúdo anecoico.","D":"nódulo sólido-cístico, com fluxo ao Doppler."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947649","ankiGuid":"o<{E_i+Xgc"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-e0244c24b78ddaf3","number":"0230m","sourceNumber":"0230m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"As recomendações do Ministério da Saúde para rastreamento do câncer de mama incluem","options":{"A":"estímulo ao ensino do autoexame como método de rastreamento do câncer de mama.","B":"mamografia bienal em mulheres com menos de 50 anos.","C":"mamografia anual em mulheres com 75 anos ou mais.","D":"mamografia bienal em mulheres com idade entre 50 e 69 anos.","E":"mamografia bienal em mulheres com idade entre 60 e 69 anos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947650","ankiGuid":"l4<Z(c;5mA"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-31f56c0401da88ad","number":"0231m","sourceNumber":"0231m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 39 anos queixa-se de nódulo na mama esquerda. Ao exame, o nódulo é palpável, com consistência fibroelástica medindo 1,5 cm. O achado ultrassonográfico que sugere benignidade:","options":{"A":"Formato redondo com até 3 lobulações.","B":"Presença de microcalcificações puntiformes isoladas.","C":"Altura maior que largura.","D":"Tamanho visível maior que 2 cm.","E":"Margens não identificadas em relação ao parênquima mamário adjacente."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947651","ankiGuid":"O&>i{tM]c2"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-806096a5b5e27e80","number":"0232m","sourceNumber":"0232m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O rastreioe o diagnóstico precoce de neoplasias fazem parte do atendimento na Rede de Atenção Primária. Considerando isso, suponha que uma mulher de 53 anos de idade procure uma unidade básica de saúde para realização de exames de rotina, e o médico da Atenção Primária perceba, na face dela, uma pequena lesão papulosa, de cor rósea, aspecto “perolado”, com finos vasos em sua superfície. Ao ser questionada, a paciente informa que essa lesão apresentou crescimento lento e progressivo. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue os itens a seguir. Na faixa etária dessa paciente, segundo o Ministério da Saúde, está indicada a realização de mamografia a cada dois anos.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947652","ankiGuid":"HvfHnhqL}O"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-64d9d371f724e0a5","number":"0233m","sourceNumber":"0233m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para revisão. Refere realizar exames ginecológicos de rastreamento, conforme orientação do médico clínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por histórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia. Recentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e etilista desde os 23 anos de idade, e o peso atual dela é 54 kg. Teve dois partos vaginais prévios, menarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição hormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde para exames de rastreamento e nos conhecimentos médicos correlatos, julgue os itens a seguir. A paciente deve realizar a mamografia anualmente.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947653","ankiGuid":"Jnvw2Bd)_j"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-df2eff06c18494ef","number":"0234m","sourceNumber":"0234m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente com 50 anos de idade percebe nódulo em sua mama direita com aproximadamente 2cm, indolor, móvel e bem delimitado, com mamografia mostrando Birads III e a ecografia IV. Qual a melhor conduta?","options":{"A":"Indicar punção biópsia.","B":"Solicitar ressonância magnética e Pet Scan.","C":"Realizar punção aspirativa para citologia oncótica.","D":"Realizar a exerese ampla da lesão para diagnóstico definitivo e tratamento.","E":"Devido às características benignas pela descrição dos exames, aguardar 6 a 12 meses e repetir exame."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947654","ankiGuid":"OgR+7>2.O("},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d59566fb7f8f976b","number":"0235m","sourceNumber":"0235m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Em uma consulta médica na atenção primária à saúde, uma mulher de 55 anos relata nunca ter feito mamografia, que não tem antecedentes familiares de câncer de mama e que não tem opinião formada sobre fazer ou não o exame. Embora haja polêmica na literatura científica sobre o tema, e por causa dela, assinale a conduta mais indicada para o médico:","options":{"A":"Mostrar a necessidade urgente da realização do exame.","B":"Mostrar o amplo balanço danos × benefícios favorável aos benefícios desse rastreamento, sugerindo que o realize.","C":"Mostrar o balanço danos × benefícios desfavorável ou duvidoso desse rastreamento sugerindo que não o realize.","D":"Mostrar o balanço danos × benefícios fracamente favorável desse rastreamento sugerindo que o realize.","E":"Mostrar para ela os danos e benefícios potenciais do rastreamento para que ela decida de forma informada."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947655","ankiGuid":"LpLY_-3Nsm"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-57e1d72292abc702","number":"0236m","sourceNumber":"0236m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher na menopausa, com 53 anos, realiza uma mamografia de rotina que apresenta um laudo com “microcalcificaçõções pleomórficas finas agrupadas, lineares e ramificadas, seguindo o trajeto ductal e densidade assimétrica em quadrante superior externo da mama esquerda”. Em sua última mamografia, realizada há dois anos, não apresentava essas alterações. Utilizando o método BI-RADS™ (Breast Imaging Reporting and Data System), o achado na mamografia dessa paciente e mais compatível com classificação:","options":{"A":"0","B":"3","C":"4","D":"5","E":"6"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947656","ankiGuid":"Dx:l:|[_d!"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-6fc1f106e16aa6c1","number":"0237m","sourceNumber":"0237m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Em relação ao rastreamento de câncer de mama na rede pública, o Ministério da Saúde recomenda a realização da mamografia em mulheres com idade","options":{"A":"entre 40 e 65 anos, anualmente.","B":"entre 50 e 65 anos, anualmente.","C":"entre 50 e 69 anos, a cada dois anos.","D":"acima de 50 anos, a cada dois anos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947657","ankiGuid":"d}EfBo&ZDE"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-8faaf7ea262bde46","number":"0238m","sourceNumber":"0238m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 30 anos, nuligesta, apresenta nódulo de mama direita, palpável, indolor e que persiste após 1 ciclo menstrual. Relata que uma tia teve câncer de mama aos 60 anos. O ultrassom de mamas evidenciou nódulo sólido de 1,8 cm - BI- RADS-3. Qual seria a melhor conduta, de acordo com as diretrizes de conduta para diagnóstico e terapêutica?","options":{"A":"Em mulheres com nódulos palpáveis BI-RADS-3 deve ser indicada exérese da lesão, independentemente dos sintomas.","B":"As lesões BI-RADS 3 podem ter seguimento semestral por até três anos, não sendo indicada a biópsia para esta conduta.","C":"A exérese cirúrgica de lesões mamárias BI-RADS-3 deve ser priorizada aos casos assintomáticos e com história familiar, pois apresentam maior risco para câncer de mama.","D":"Até a terceira década de vida, a maioria dos nódulos sólidos da mama não necessita de investigação; no entanto, quando o nódulo é palpável, recomenda-se mamografia de rastreamento."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947658","ankiGuid":"bbBW]v^J@8"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-e95981ce2447ba3d","number":"0239m","sourceNumber":"0239m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"“O Canadian Radiographic Breast Screening Study: randomised screening trial ” chegou à conclusão de que o screening por mamografia não reduz a mortalidade por câncer de mama nas faixas etárias de 40- 49 anos e de 50-69 anos, após um seguimento de 25 anos de suas 89.835 participantes. Em revisão sistemática de oito estudos randomizados, em 2013, incluindo 600.000 mil mulheres entre 39 e 74 anos, Gøetzche conclui que o malefício causado pelo sobrediagnóstico sobrepõe-se ao benefício da detecção precoce: de 2.000 mulheres submetidas ao rastreamento por 10 anos, uma vai evitar a morte por câncer de mama, mas 10 mulheres saudáveis serão tratadas desnecessariamente e 200 mulheres experimentarão estresse psicológico por conta de falsos positivos no exame”. Sobre o rastreamento de câncer de mama, considerando riscos e benefícios envolvidos, assinale a alternativa correta em relação às recomendações atuais do Ministério da Saúde e Instituto Nacional do Câncer:","options":{"A":"Mamografia anual a partir dos 40 anos","B":"Mamografia bienal para mulheres entre 50 e 69 anos","C":"Mamografia bienal a partir dos 40 anos","D":"Mamografia anual para mulheres entre 50 e 69 anos"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947659","ankiGuid":"Qx9ID6]ggL"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-502a83f08a5034af","number":"0240m","sourceNumber":"0240m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 45 anos trouxe à consulta mamografia mostrando lesão nodular à esquerda categorizada como BIRADS 4B. A ultrassonografia mamária revelou uma lesão de 2 cm, hipoecogênica, com bordas mal delimitadas, crescimento anteroposterior, com 1,5 cm de diâmetro, localizada no quadrante inferomedial da mama esquerda, classificada também como BIRADS 4B. Ao exame físico, não foram palpados linfonodos axilares ou em fossa supraclavicular suspeitos. Na mama esquerda, em local correspondente ao do nódulo, foi palpado nódulo mal definido, não aderido à pele ou a planos profundos. Com base no quadro, a conduta mais adequada é","options":{"A":"realização de biópsia percutânea com agulha grossa.","B":"realização de mamografia com compressão focada.","C":"realização de ressonância magnética.","D":"realização de biópsia excisional.","E":"reavaliação em 6 meses com nova ultrassonografia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947660","ankiGuid":"DqXW:i)jl#"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-1180fb4d2e0dc9b8","number":"0241m","sourceNumber":"0241m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"O médico de família e comunidade recebeu Cláudia, de 43 anos de idade, que foi a seu consultório por indicação de um amigo. Nega comorbidades, uso de medicamentos ou histórico familiar de doenças. Faz uso de álcool (um copo de caipirinha aos finais de semana), não fuma e pratica atividade física três vezes por semana. Nega doenças na família. Gostaria de fazer todos os exames que têm direito pelo plano e sempre teve o hábito de fazer exames anuais, mas os últimos foram há dois anos e estavam normais (Papanicolau, mamografia, ultrassonografia transvaginal e de tireoide e exame de sangue). Ao exame físico, sem alterações, pressão arterial de 108 x 72 mmHg e IMC de 28. Com base nessa situação hipotética, nas orientações de rastreamento do Ministério da Saúde e nas revisões do US Task Force, assinale a alternativa incorreta.","options":{"A":"A mamografia não está indicada nesse momento para o rastreamento de câncer de mama em Cláudia.","B":"A ultrassonografia transvaginal está indicada como forma de rastreamento de câncer de ovário, com ou sem dosagem de CEA e CEA 125.","C":"O Papanicolau não está indicado para Cláudia nesse momento.","D":"O Papanicolau é contraindicado em pacientes com menos de 21 anos de idade sem histórico de HIV e(ou) aumento de risco para câncer cervical.","E":"A ultrassonografia de tireoide não está indicada para rastreamento de câncer de tireoide."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947661","ankiGuid":"HW^6,U$aBP"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-e169761957f60397","number":"0242m","sourceNumber":"0242m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 41 anos procurou ginecologista com queixa de nódulo em mama direita há 30 dias sem dor. O exame ginecológico foi normal, inclusive o exame das mamas. Foi solicitada mamografia cujo resultado foi BI-RADS 3 com achado de microcalcificações tipo \"\"cálcio de leite\"\" no quadrante superior externo da mama direita. Diante desses achados, a conduta deve ser:","options":{"A":"repetir a mamografia em 6 meses.","B":"fazer punção biópsia com agulha fina.","C":"fazer punção biópsia com agulha grossa.","D":"fazer mamotomia.","E":"fazer exérese cirúrgica da lesão com linfonodo sentinela."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947662","ankiGuid":"DqU.fY-%AX"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-7277c9632b17fd37","number":"0243m","sourceNumber":"0243m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher com 41 anos, G2P2, lactou duas vezes por até um ano, refere que fez a primeira mamografia de rastreamento há quinze dias. Como o laudo mostrou BI- RADS®3, veio à consulta para esclarecer algumas dúvidas. Deseja nova gestação e gostaria de engravidar novamente o mais breve possível, pois teme ter dificuldades e está preocupada com possível gestação de risco. Qual orientação dar a esta paciente?","options":{"A":"Pede para retornar em um ano com nova mamografia e, também, ultrassonografia mamária.","B":"Prossegue a investigação com novos exames de imagens e até biópsia se necessário, antes da gravidez","C":"Pede para a paciente aguardar dois anos, mantendo seguimento semestral com mamografia.","D":"Tentar engravidar, pois na classificação BI-RADS®3 o risco malignidade é baixo."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947663","ankiGuid":"Pi:wGQK]FP"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-684d9edcfe38821d","number":"0244m","sourceNumber":"0244m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 67 anos de idade, cozinheira, vem para consulta, com demanda de prevenção de doenças e promoção da saúde. Nega doenças prévias. É tabagista 30 maços-ano e tem hábitos sedentários. Nega etilismo ou uso de drogas ilícitas. Ao exame clínico: dentes em mal estado de conservação, IMC= 32kg/m², circunferência abdominal 108 cm, PA= 136x70 mmHg, frequência cardíaca= 76bpm, sem outras alterações. Dentre as alternativas abaixo, qual delas apresenta dois exames que devem ser solicitados para esta paciente?","options":{"A":"Densitometria óssea e colesterol total e frações.","B":"Mamografia e angiotomografia de coronárias.","C":"Ultrassonografia de abdome e glicemia de jejum.","D":"Pesquisa de sangue oculto nas fezes e teste ergométrico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947664","ankiGuid":"P&DV}8ufdq"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-2ae87bfd66c48af5","number":"0245m","sourceNumber":"0245m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 41 anos realizou sua primeira mamografia e levou-a ao ginecologista. O exame apontou para um nódulo regular, arredondado com 0,6 cm no quadrante inferior externo da mama direita – BI-RADS 3. Assinale a alternativa que apresenta a interpretação e a conduta corretas frente a esse achado.","options":{"A":"Suspeita moderada de malignidade – repetir o exame mamográfico a cada 6 meses.","B":"Grande suspeita de malignidade – realizar biópsia excisional.","C":"Achado provavelmente benigno – repetir exames mamográficos anualmente.","D":"Achado provavelmente benigno – repetir exame mamográfico a cada seis meses.","E":"Suspeita moderada de malignidade – realizar biópsia excisional."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947665","ankiGuid":"QEy9*[R2?:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-3b2b57d9c7665fb4","number":"0246m","sourceNumber":"0246m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 55a, procura atendimento médico por alteração de exames de rotina. Mamografia: nódulo na mama esquerda, irregular e microlobulado, medindo 18mm. Ultrassonografia: nódulo hipoecóico, irregular e microlobulado, BIRADS® 5. A CONDUTA É:","options":{"A":"Punção aspirativa por agulha fina.","B":"Biópsia percutânea de fragmento “core-biopsy”.","C":"Biópsia incisional com avaliação intra-operatória","D":"Biópsia excisional seguida de congelação"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947666","ankiGuid":"N4CamLC7U^"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-c7951dd722f66e8b","number":"0247m","sourceNumber":"0247m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Cada vez mais se exigem transparência, clareza, objetividade e simplicidade sobre os benefícios e danos potenciais nas orientações profissionais e institucionais sobre os rastreamentos. Dentre as orientações a uma mulher de 51 anos que nunca fez rastreamento mamográfico e pergunta sobre ele, é correto orientar que:","options":{"A":"Para cada morte evitada por câncer de mama (benefício), cerca de 3 ou 4 mulheres são diagnosticadas e tratadas sem necessidade (dano), pois seu câncer não se manifestaria.","B":"O tratamento permitido pelo diagnóstico precoce salva vida (benefício) e os danos principais são os falso- positivos, que serão minimizados com o resultado da biópsia.","C":"O benefício é evitar mortes tratando precocemente o câncer se detectado e os danos principais são os falso- positivos e as biópsias desnecessárias, que porém são temporárias.","D":"O benefício é reduzir de 15 a 20% a mortalidade por esse câncer (de 5 para 4 mortas em mil mulheres, nos ensaios clínicos), e os danos principais são a dor do exame e os falso-positivos.","E":"O benefício é reduzir em 30% a mortalidade por esse câncer e os danos são: falso positivos, biópsias desnecessárias, sobrediagnósticos e aumento da mortalidade cardiovascular."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947667","ankiGuid":"yf&u=`V??7"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-0410d85c2d91365a","number":"0248m","sourceNumber":"0248m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente realizou mamografia que não definiu uma lesão adequadamente, sendo considerada um exame incompleto. A classificação de BI-Rads e a conduta referente a esse exame, respectivamente, são:","options":{"A":"BI-Rads 0 / complementar com ultrassonografia mamária","B":"BI-Rads 1 / complementar com ressonância mamária","C":"BI-Rads 5 / repetir exame em 1 ano","D":"BI-Rads 0 / realizar biópsia mamária"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947668","ankiGuid":"N3Z8HKovR:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-65f4ac14b914dd17","number":"0249m","sourceNumber":"0249m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 28 anos, com massa palpável em mama direita, indolor, móvel de cerca 3cm. Ultrassonografia: BI-RADS 3. Mamografia complementar: BI-RADS 4. A conduta mais adequada para esta paciente é:","options":{"A":"acompanhamento clínico","B":"ressonância nuclear magnética","C":"core biopsia","D":"segmentectomia com linfonodo sentinela"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947669","ankiGuid":"vbIC(6|w&r"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-413ca391de00b870","number":"0250m","sourceNumber":"0250m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 61 anos realizou mamografia que evidenciou nódulo espiculado medindo cerca de 3cm, categoria 5 no sistema BI-RADS. Qual a conduta mais adequada para o caso?","options":{"A":"Repetir mamografia em 6 meses.","B":"Biópsia percutânea (core biopsy) guiada por ultra-sonografia.","C":"Quadrantectomia com esvaziamento axilar.","D":"Biópsia cirúrgica com marcação por estereotaxia.","E":"Punção aspirativa por agulha fina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947670","ankiGuid":"Qdd~4&EJ:;"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-ba20b1260658d105","number":"0251m","sourceNumber":"0251m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Vem para consulta uma mulher de 50 anos com o seguinte histórico: quatro gestações, todas terminaram em parto por via vaginal, ainda menstrua regularmente. Seu esposo e único parceiro sexual da vida foi submetido a vasectomia logo após o nascimento de seu último filho há 15 anos e está impotente há 1 ano por complicações de um Diabete. A paciente faz acompanhamento com um clínico e seus exames laboratoriais, recentes estão normais. Afirma não ter realizado nenhuma consulta com ginecologista nos últimos sete anos. Nega casos de câncer de ovário ou de mama em familiares de primeiro grau. Assinale a alternativa que descreve os exames que devem ser solicitados para prevenção do câncer. I - Citologia oncótica, mamografia, ecografia mamaria, ecografia pélvica transvaginal. II - Citologia oncótica, colonoscopia, mamografia, rastreamento da pele para lesões cutâneas. III - Citologia oncótica, mamografia, CA-125, CA 19-9. IV - Colonoscopia, mamografia, rastreamento de pele para lesões cutâneas e pesquisa de CA-125.","options":{"A":"A afirmativa II é a única correta.","B":"A afirmativa IV é a única correta.","C":"As afirmativas I e III estão corretas.","D":"As afirmativas II e III estão corretas.","E":"As afirmativas III e IV estão corretas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947671","ankiGuid":"b:}04hq0=J"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-7aa2de1ab065b133","number":"0252m","sourceNumber":"0252m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente com 50 anos de idade percebe nódulo em sua mama direita com aproximadamente 2cm, indolor, móvel e bem delimitado com mamografia mostrando Birads III e a ecografia IV. Qual a melhor conduta?","options":{"A":"Devido às características benignas pela descrição dos exames, aguardar 6 a 12 meses erepetir exame.","B":"Realizar a exerese ampla da lesão para diagnóstico definitivo e tratamento.","C":"Realizar punção aspirativa para citologia oncótica.","D":"Solicitar ressonância magnética e Pet Scan.","E":"Indicar punção biópsia por agulha grossa."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947672","ankiGuid":"MR7}N1`|cu"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-14198748cd819181","number":"0253m","sourceNumber":"0253m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 45 anos, assintomática, submetida a exames de rastreamento mamográfico com os seguintes achados: \"\"Mamas heterogeneamente densas, apresentando microcalcificações pleomórficas agrupadas no quadrante supero lateral da mama direita, linfonodos nos prolongamentos axilares com características radiológicas normais\"\". A correta classificação BIRADS dessa mamografia e a melhor conduta frente ao achado são respectivamente:","options":{"A":"BIRADS 0 / Complementação com ultrassonografia mamária devido a alta densidade do parênquima.","B":"BIRADS 3 / Acompanhamento semestral por imagem das microcalcificações.","C":"BIRADS 4 / Core biópsia guiada por estereotaxia na área de microcalcificações.","D":"BIRADS 4 / Ressecção com marcação pré-cirúrgica na área de microcalcificações."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947673","ankiGuid":"wjitxl4<%#"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-a320f066242a0f2c","number":"0254m","sourceNumber":"0254m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 35 anos procura a UBS preocupada porque sua vizinha de 40 anos está com câncer de mama e quer orientação sobre o rastreamento. No momento está assintomática e informa G1P1A0, que amamentou seu filho, agora com cinco anos, por sete meses, é sexualmente ativa e o último exame preventivo do colo uterino foi em março de 2019, com laudo negativo para malignidade. Usa DIU T de cobre há três anos e seus ciclos menstruais são regulares. Nega casos de câncer de mama ou ovário na sua família e não é tabagista. Não foram evidenciadas alterações no exame das mamas. Das seguintes condutas, a que NÃO ESTÁ INDICADA para essa paciente é:","options":{"A":"informar que ela não é considerada de alto risco para câncer de mama, já que o examedas mamas está normal e a história clínica (pessoal e familiar) não é positiva.","B":"orientar sobre a limitação da mamografia em mulheres jovens e a recomendação doinício do rastreamento aos 50 anos, segundo o Ministério da Saúde, compartilhando a decisão com ela.","C":"orientar sobre ações de prevenção primária do câncer de mama: manter o peso numafaixa saudável e a praticar atividade física, além de evitar consumo de álcool.","D":"solicitar ultrassonografia das mamas por causa da idade da paciente, após término demenstruação, para investigar possível câncer."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947674","ankiGuid":"s2VME3)Pdf"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-150f9f1e72e82227","number":"0255m","sourceNumber":"0255m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Rastreamento nas pacientes de alto risco Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento vaginal acinzentado e com odor fétido na última semana. Refere também que gostaria de realizar check-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria mãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica pregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de idade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse caso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir. Deverá ser solicitada mamografia de rastreamento para a paciente. A história descrita de câncer na mãe, aos 68 anos de idade, não indicaria o rastreamento da paciente em idade mais precoce que a população de baixo risco.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947675","ankiGuid":"Ala2EYmKjZ"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-1531138d4b1e57ef","number":"0256m","sourceNumber":"0256m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 35 anos, assintomática, história familiar negativa para câncer de mama, procura a Unidade Básica de Saúde para solicitação de mamografia de rastreamento. De acordo com as recomendações do Ministério da Saúde, sobre o rastreamento e estratégias de diagnóstico precoce do câncer de mama, qual alternativa é considerada adequada?","options":{"A":"A mamografia é recomendada a partir dos 40 anos de idade, pois em faixas etárias menores as mamas são mais densas e a sensibilidade da mamografia é reduzida, aumentando a taxa de exames falsos negativos.","B":"O rastreamento mamográfico pode identificar cânceres de comportamento indolente, que não ameaçariam a vida da mulher e que resultam em sobrediagnóstico e sobretratamento, expondo-a a riscos e danos associados.","C":"Estratégias para redução da mortalidade por câncer de mama envolvem o acesso à ultrassonografia mamária de rastreamento, além do controle de fatores de riscos e efetividade da rede assistencial.","D":"Não é recomendada a realização de estratégias de conscientização, devido sua muito baixa efetividade e possíveis danos associados às pacientes."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947676","ankiGuid":"Q(n}$$vXkS"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d773e76bae9939a8","number":"0257m","sourceNumber":"0257m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Uma mulher de 57 anos, assintomática, comparece para consulta na atenção primária. Trouxe consigo uma mamografia, a primeira que realizou na vida. Após avaliação, o médico decide solicitar retorno e uma nova mamografia com intervalo de seis meses. A paciente não possui histórico familiar e pessoal relevante. Segundo as diretrizes do Ministério da Saúde / Instituto Nacional de Câncer, o que o médico deve ter evidenciado nos resultados dessa mamografia?","options":{"A":"BI-RADS 0","B":"BI-RADS 1","C":"BI-RADS 3","D":"BI-RADS 5"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947677","ankiGuid":"BhIT$7i]Mg"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-87db5776440de010","number":"0258m","sourceNumber":"0258m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 55 anos, sem antecedentes patológicos, nuligesta, com laudo de mamografia BI-RADS 2. A conduta nesse caso é:","options":{"A":"complementar com ultrassom.","B":"biópsia dirigida por ultrassom caso o nódulo não seja palpável.","C":"complementar com ressonância magnética.","D":"mamografia de rotina anual.mamografia de rotina anual."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947678","ankiGuid":"fem<|Z~fAF"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-f5c65145afddaa12","number":"0259m","sourceNumber":"0259m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 30 anos de idade, com história familiar de câncer de mama da irmã de 35 anos. Qual melhor conduta preventiva a ser realizada?","options":{"A":"Tranquilizar paciente pois o risco só aumenta quando há 2 casos na família","B":"Orientar exame clínico a cada seis meses e ultrassonografia mamária.","C":"Iniciar uso oral de Tamoxifeno.","D":"Realizar ressonância ou mamografia de início imediato","E":"Realizar Salpingoooforectomia bilateral e mastectomia bilateral"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947679","ankiGuid":"kW-svy{dZp"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-5e31071c4fc22388","number":"0260m","sourceNumber":"0260m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 53 anos procura UBS com queixa de mastalgia, mais localizada em mama esquerda. AF: mãe e uma irmã com câncer de mama antes dos 50 anos. Exame físico: mamas sem nódulos palpáveis. Mamografia: mamas lipossubstituídas, nódulo pouco denso, regular, medindo cerca de 0,5 cm de diâmetro em quadrante superior externo da mama direita (compatível com linfonodo intramamário) = BIRADS 2. A conduta é","options":{"A":"nova mamografia em um ano.","B":"nova mamografia em dois anos.","C":"ultrassonografia das mamas para complementar a mamografia.","D":"nova mamografia em 6 meses."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947680","ankiGuid":"J/))}|qAAt"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-1a049bd56500f1df","number":"0261m","sourceNumber":"0261m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 52 anos de idade realizou mamografia de rastreamento (imagem abaixo).\n\nO exame físico é normal. Qual a melhor conduta para o caso?","options":{"A":"Biópsia cirúrgica.","B":"Aspiração com agulha fina.","C":"Biópsia percutânea com agulha grossa.","D":"Ressonância magnética."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":["question_bank/media/ginecologia-rastreamento-do-cancer-de-mama/paste-2c946f48029602c2f0b500589db5ca8a7444622d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947681","ankiGuid":"O!JiQBaHNT"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-ad7d439bdad668a7","number":"0262m","sourceNumber":"0262m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 45 anos, realiza mamografia de rotina e tem a classificação BI-RADS 0 (American College of Radiology Breast Imaging Reporting and Data System). A designação 0 (zero) quer dizer:","options":{"A":"Necessita de avaliação adicional","B":"Lesão benigna","C":"Suspeita de malignidade","D":"Lesão provavelmente benigna"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947682","ankiGuid":"q5vR)+Pl6J"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-85d1a34f0daafa6b","number":"0263m","sourceNumber":"0263m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 36a, G3P2C0A1, procura Unidade Básica de Saúde por nódulo indolor em mama direita percebido há quatro meses, retorna com exames solicitados. Refere que não menstrua há 3 anos, em uso trimestral de acetato de medroxiprogesterona de depósito. Antecedentes oncológicos familiares: tia materna com câncer de mama tratado na pré-menopausa (viva) e avó paterna com câncer de mama tratado pós-menopausa (falecida). Mamografia: BIRADS® = 0 e ultrassonografia de mamas: lesão 15 mm hipoecoide, microlobulada e irregular em mama esquerda, BIRADS® = 4. Exame das mamas: pequeno volume, ptose grau 1, levemente assimétricas, sendo a esquerda de menor tamanho. Mama esquerda com discreto abaulamento da pele na junção dos quadrantes superiores à inspeção estática; à palpação, identificada nodulação única de aproximadamente 20 mm de diâmetro; mama direita semiologicamente normal; expressão das árvores ductais negativas bilateralmente. Axilas e fossas supraclaviculares bilateralmente livres. A CONDUTA É:","options":{"A":"Repetir ultrassonografia de mama em 6 meses.","B":"Solicitar tomografia computadorizada de mamas.","C":"Repetir mamografia com magnificação em 3 meses.","D":"Encaminhar ao centro de referência."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947683","ankiGuid":"FR}<,#90)b"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-06fccdcf282471dc","number":"0264m","sourceNumber":"0264m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Uma mulher de 42 anos, ao investigar nodulação palpável em quadrante superior externo da mama esquerda, realizou exame de ultrassonografia com achado de imagem anecoica, ovalada e homogênea, medindo 1,5 cm de diâmetro médio. Qual a classificação BI-RADS (Breast Imaging-Reporting and Data System) do exame e qual a conduta recomendada?","options":{"A":"BI-RADS 1. Controle anual com mamografia.","B":"BI-RADS 2. Controle semestral com ultrassonografia.","C":"BI-RADS 2. Não é necessária investigação adicional.","D":"BI-RADS 3. Punção aspirativa para citologia.","E":"BI-RADS 3. Avaliação histológica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947684","ankiGuid":"v=|(krFX;B"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-0c03da867144d3d7","number":"0265m","sourceNumber":"0265m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 35 anos veio à consulta, encaminhada da Unidade Básica de Saúde, por ter palpado um nódulo na mama esquerda. Trouxe ultrassonografia mostrando nódulos hipoecogênicos, com sombra acústica posterior, de limites definidos e crescimento paralelo ao tecido subcutâneo. Dois nódulos foram visualizados na mama direita, no quadrante inferomedial, com 0,8 e 1 cm de diâmetro, e eram impalpáveis. O outro nódulo, com 3 cm de diâmetro, localizava-se no quadrante superolateral da mama esquerda. À palpação, era móvel, fibroelástico e com limites definidos. Qual a hipótese diagnóstica mais provável e qual a conduta mais adequada para investigar o nódulo da mama esquerda?","options":{"A":"Nódulo cístico - biópsia percutânea por agulha grossa","B":"Fibroadenoma - biópsia percutânea por agulha grossa","C":"Carcinoma ductal infiltrante - biópsia excisional e exame anatomopatológico por congelação","D":"Tumor filodes - biópsia percutânea por agulha grossa","E":"Carcinoma lobular - punção aspirativa por agulha fina"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947685","ankiGuid":"p@$U`p#Q)E"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-831385e229d2eb29","number":"0266m","sourceNumber":"0266m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente veio encaminhada da Unidade Básica de Saúde por mamografia classificada como BI-RADS 4C devido à presença de microcalcificações pleomórficas. Ao exame físico, não foram encontradas alterações. Qual a conduta mais adequada?","options":{"A":"Encaminhar a paciente para biópsia guiada por mamografia (agulhamento).","B":"Repetir a mamografia em 6 meses.","C":"Repetir a mamografia anualmente.","D":"Realizar ressonância magnética.","E":"Realizar tomossíntese."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947686","ankiGuid":"|DHQ5iRVH"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-38fed5675670b804","number":"0267m","sourceNumber":"0267m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Para mamas extremamente densas à mamografia, que podem diminuir a sensibilidade para 40 a 50% é recomendado que se complemente com outro exame que, na maioria dos casos, é o(a):","options":{"A":"Tomografia computadorizada.","B":"Ultrassonografia mamária bilateral.","C":"Autoexame das mamas.","D":"Mamotomia (core biopsy a vácuo)."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947687","ankiGuid":"FX5RjJOo=]"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-c4b67690fd608565","number":"0268m","sourceNumber":"0268m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Segundo o Ministério da Saúde, o rastreamento do câncer de mama deve ser realizado nas mulheres entre 50 e 69 anos através de:","options":{"A":"autoexame e mamografia a cada ano, se normais","B":"autoexame e mamografia a cada dois anos, se normais","C":"exame clínico das mamas anual e mamografia a cada um ano, se normais","D":"exame clínico das mamas anual e mamografia, a cada dois anos, se normais"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947688","ankiGuid":"jEstw9+>H:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-98f909ae73e2dc10","number":"0269m","sourceNumber":"0269m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Os achados encontrados nos exames mamográficos devem ser descritos como nódulos, calcificações ou distorção de arquitetura, além de alterações associadas, como espessamento de pele e retração cutânea. O achado mamográfico mais comum do carcinoma ductal in situ é a presença de","options":{"A":"nódulos com calcificações “em pipoca”.","B":"calcificações em anel, com o centro radiotransparente.","C":"nódulos com densidade de gordura.","D":"microcalcificações com morfologia arboriforme ou pleomórficas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947689","ankiGuid":"g;;45ZA:}}"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-42d3b7c4589ccb5e","number":"0270m","sourceNumber":"0270m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"M.M.H.I., sexo feminino, 54 anos, casada, GIIPIIA0, doméstica, sem história prévia de enfermidades, vem ao ambulatório para consulta de rotina depois de ficar 5 anos sem avaliação médica. Durante a entrevista, relatou que vem observando certa sensação de cansaço, desânimo para com as tarefas diárias, insônia, e “um calor exagerado”. A menstruação está irregular há aproximadamente 6 meses. Nega uso de medicamentos. Nega tabagismo e etilismo. História familiar positiva para câncer de mama (mãe que faleceu aos 57 anos de idade), diabetes e hipertensão arterial. Dentre outros exames, foi solicitada a mamografia bilateral (MMG). Duas semanas depois, a paciente retorna ao ambulatório para mostrar o resultado dos exames, em que se observa BI-RADS 0 (ZERO) como resultado de sua MMG. Na terminologia BI-RADS (American College of Radiology Breast Imaging Reporting and Data System), a designação 0 (ZERO) significa","options":{"A":"necessidade de avaliação adicional.","B":"mamografia normal.","C":"suspeita de malignidade.","D":"lesão provavelmente benigna."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947690","ankiGuid":"f?,~sO~oSf"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-c50ba231c298f9ca","number":"0271m","sourceNumber":"0271m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente, G4P2A2, 61 anos procurou o ambulatório de mastologia apresentando mamografia classificada como BI-RADS 2. Qual a melhor conduta?","options":{"A":"biópsia cirúrgica com marcação por estereotaxia","B":"mamotomia","C":"Seguimento clínico","D":"core biopsy guiada por ultrassonografia","E":"quadrantectomia com esvaziamento axilar"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947691","ankiGuid":"nT5<!D],!["},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-aab8abf17a394ce0","number":"0272m","sourceNumber":"0272m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Viúva de 75 anos, sem atividade sexual desde os 50 anos, faz exames de rastreio para câncer de colo, mama e ovário desde os 40 anos. Ela realiza anualmente mamografia, exame Papanicolau e ultrassonografia de pelve. A paciente procurou o médico muito assustada, pois sua mamografia apresentou resultado BIRADS 3. Os rastreios realizados por essa paciente e o resultado da última mamografia, respectivamente, evidenciam que:","options":{"A":"foram seguidas as orientações do Ministério da Saúde e há sólidas evidências desse benefício / alta probalidade de câncer de mama","B":"foram seguidas as orientações do Ministério da Saúde e há dúvidas importantes sobre esse benefício / alta probabilidade de câncer de mama","C":"não foram seguidas as orientações do Ministério da Saúde e há sólidas evidências desse benefício / baixa probalidade de câncer de mama","D":"não foram seguidas as orientações do Ministério da Saúde e há dúvidas importantes sobre esse benefício / baixa probabilidade de câncer de mama"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947692","ankiGuid":"lyHhcz_$+v"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-b8a6dc8a34f29b3a","number":"0273m","sourceNumber":"0273m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 59 anos, assintomática, comparece ao ambulatório para exames de prevenção. O exame físico mamário é normal. É submetida à mamografia, cujo laudo mostra microcalcificações agrupadas no quadrante súpero-lateral, categoria 5 do sistema BI-RADS. A melhor conduta a seguir é:","options":{"A":"acompanhamento semestral.","B":"punção aspirativa por agulha fina","C":"biópsia de congelação.","D":"biópsia guiada por mamografia","E":"punção por agulha grossa ambulatorial."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947693","ankiGuid":"x?XqSm6rD$"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-e8111bc10d522d76","number":"0274m","sourceNumber":"0274m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 60 anos de idade, gesta 1, para 0, aborto 1, menopausada há 10 anos, vem a consulta no ambulatório de climatério. PA: 130x80 mmHg. Nega uso de terapia hormonal. Antecedentes pessoais: hipotireoidismo em uso de levotiroxina 75 mcg/dia. IMC: 35. Traz os seguintes exames: lipidograma dentro dos parâmetros da normalidade. Glicemia de jejum: 99 mg/dL. TSH: 2,1 mU/L. Mamografia e ecografia mamária BIRADS 3. Ecografia endovaginal: volume uterino 92 cm³. Endométrio 7 mm. Duas imagens intracavitárias hipo e hiperecoicas mescladas dentro do endométrio medindo 20x25 mm a primeira e 25x28 mm a segunda. Paciente está assintomática. Com base no quadro apresentado, deve-se:","options":{"A":"Repetir mamografia e ecografia mamária em 12 meses.","B":"Repetir mamografia e ecografia mamária em 6 meses e indicar histeroscopia.","C":"Solicitar ressonância magnética nuclear das mamas e indicar dilatação e curetagem uterina.","D":"Repetir mamografia em 3 meses associada a ressonância magnética nuclear e indicar histeroscopia.","E":"Solicitar ressonância magnética nuclear das mamas e indicar histeroscopia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947694","ankiGuid":"Qa5sE.#1Jx"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-a60b2e493ee96eb5","number":"0275m","sourceNumber":"0275m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"A mamografia é um exame de rastreio por imagem, que tem como finalidade estudar o tecido mamário. Em uma mamografia classificada como categoria 3 (BI-RADS), qual a conduta a ser seguida?","options":{"A":"Controle anual.","B":"Biópsia cirúrgica.","C":"Controle trimestral.","D":"Controle semestral.","E":"Biópsia percutânea."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947695","ankiGuid":"C?(7KG+i)?"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-cb138dd5232939be","number":"0276m","sourceNumber":"0276m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Determinada paciente de 55 anos de idade apresenta, em exame físico, nódulo mamário em quadrante superior externo de mama esquerda, redondo, de margem circunscrita, de aproximadamente 1 cm x 1 cm, sem outros sintomas associados. A pressão arterial na consulta era de 120 mmHg x 80 mmHg, FC de 75 bpm e 18 irpm, saturando 99% em ar ambiente. Ela então comparece ao exame levando o resultado da mamografia que foi solicitada em última consulta. Nega mamografias prévias. Em laudo, consta classificação de BI-RADS 0 (zero). A respeito desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Uma conduta apropriada é realizar biópsia guiada por ultrassonografia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947696","ankiGuid":"yj`WqGl4hk"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-7d8b463b029f3cb5","number":"0277m","sourceNumber":"0277m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Determinada paciente de 55 anos de idade apresenta, em exame físico, nódulo mamário em quadrante superior externo de mama esquerda, redondo, de margem circunscrita, de aproximadamente 1 cm x 1 cm, sem outros sintomas associados. A pressão arterial na consulta era de 120 mmHg x 80 mmHg, FC de 75 bpm e 18 irpm, saturando 99% em ar ambiente. Ela então comparece ao exame levando o resultado da mamografia que foi solicitada em última consulta. Nega mamografias prévias. Em laudo, consta classificação de BI-RADS 0 (zero). A respeito desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. BI-RADS 0 é um achado de bom prognóstico.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947697","ankiGuid":"EO+aC=-<gp"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-4fe94bc70362f4c9","number":"0278m","sourceNumber":"0278m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Determinada paciente de 55 anos de idade apresenta, em exame físico, nódulo mamário em quadrante superior externo de mama esquerda, redondo, de margem circunscrita, de aproximadamente 1 cm x 1 cm, sem outros sintomas associados. A pressão arterial na consulta era de 120 mmHg x 80 mmHg, FC de 75 bpm e 18 irpm, saturando 99% em ar ambiente. Ela então comparece ao exame levando o resultado da mamografia que foi solicitada em última consulta. Nega mamografias prévias. Em laudo, consta classificação de BI-RADS 0 (zero). A respeito desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. É importante solicitar ecografia mamária para complementar investigação.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947698","ankiGuid":"JhEh(1mBkF"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-3ebe627bf9df1d58","number":"0279m","sourceNumber":"0279m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 41 anos realizou mamografia e ultrassonografia mamária de rotina que evidenciaram imagem nodular sólida de 10 mm de diâmetro, orientação não paralela à pele, margens anguladas e sombra posterior. Tem histórico de tia materna com câncer de mama e de intestino aos 65 anos. Qual a orientação para essa paciente, de acordo com o Ministério da Saúde?","options":{"A":"Realizar quadrantectomia para exérese da lesão apresentada, diante do tamanho e do aspecto descritos.","B":"Fazer seguimento da lesão a cada 6 meses por um período de 2 ou 3 anos devido à imagem do nódulo apresentada.","C":"Solicitar ressonância magnética das mamas como parte do rastreamento devido ao elevado risco de câncer de mama hereditário.","D":"Indicar biópsia de fragmento para esclarecimento diagnóstico devido às características BIRADS 4 (suspeito de malignidade) do nódulo descrito."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947699","ankiGuid":"iI3uP/W~P:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-471c2edc4d313e0c","number":"0280m","sourceNumber":"0280m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 47 anos de idade, assintomática, realizou uma Ultrassonografia (US) de mamas que detectou nódulo de forma redonda, margens não-circunscritas, com reforço posterior e medindo 1,7 cm no maior eixo. Qual é a hipótese diagnóstica mais provável e a conduta?","options":{"A":"Câncer de mama, biopsia tipo core (agulha grossa) guiada por US.","B":"Fibroadenoma, biopsia a vácuo guiada por mamografia.","C":"Cisto complexo, biopsia tipo core (agulha grossa) guiada por US.","D":"Câncer de mama, biópsia a vácuo guiada por mamografia","E":"Fibroadenoma, punção com agulha fina guiada por US."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947700","ankiGuid":"e[BL(rvP.."},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-9ba88a0b73736d38","number":"0281m","sourceNumber":"0281m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 50 anos, realiza exame mamográfico que apresenta como conclusão BI-RADS 4A. Qual a interpretação e qual a conduta?","options":{"A":"Mamografia incompleta; necessita magnificação.","B":"Baixa suspeita para malignidade; avaliação histológica.","C":"Moderada suspeita para malignidade; core biopsy.","D":"Malignidade confirmada, mas restrita à mama; mastectomia.","E":"Alta suspeita para malignidade; tumorectomia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947701","ankiGuid":"b]_[)bCmq["},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-64c8b7010597e0ac","number":"0282m","sourceNumber":"0282m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Senhora de 70 anos procura consulta para check-up. É assintomática, sem história familiar ou pessoal de risco para patologias. Nega morbidades e nega tabagismo. Exames complementares indicados para rastreio de morbidades segundo a US Preventive Task Force incluem glicemia,","options":{"A":"mamografia, densitometria mineral óssea, ultrassonografia de tireoide, colonoscopia eurocultura.","B":"mamografia, densitometria mineral óssea, ultrassonografia de aorta abdominal eultrassonografia de tireoide.","C":"mamografia, ultrassonografia de tireoide, densitometria mineral óssea e colonoscopia.","D":"mamografia, densitometria mineral óssea e colonoscopia.","E":"densitometria mineral óssea, colonoscopia e urocultura."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947702","ankiGuid":"g+~>K%vSi]"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-b14458b36f805e0f","number":"0283m","sourceNumber":"0283m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 42 anos, cuja avó materna apresentou câncer de mama aos 80 anos, realizou mamografia com resultado de BI- RADS 3. Em relação ao rastreamento para câncer de mama, é correto afirmar que o(a):","options":{"A":"mamografia, como teste de rastreamento, tem benefícios inquestionáveis","B":"rastreamento foi bem indicado nesse caso, porque a paciente apresenta alto risco para o câncer de mama","C":"aconselhamento pré-teste informando os riscos e o seu significado é indicado, dando autonomia à paciente para realizá-lo ou não","D":"biopsia está indicada nesse caso, porque o resultado da mamografia demonstrou uma lesão de alta probabilidade para câncer de mama"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947703","ankiGuid":"BsRZ^m2Yb?"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-86b3a40b050eb677","number":"0284m","sourceNumber":"0284m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"A USG mamária é indicada para:","options":{"A":"Detectar nódulos em mamas muito adiposas.","B":"Rastrear câncer de mama.","C":"Detectar microcalcificações.","D":"Avaliar achado duvidoso na mamografia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947704","ankiGuid":"y0{&`0*F6_"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-d333578433f265db","number":"0285m","sourceNumber":"0285m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente, G2P2A0, 63 anos, procurou ambulatório de mastologia, apresentando nódulo palpável em quadrante superior da mama esquerda, na mamografia, sendo classificado como BI-RADS 3. Qual é a melhor conduta?","options":{"A":"biópsia cirúrgica com marcação por estereotaxia.","B":"mamotomia.","C":"repetir mamografia em 6 meses.","D":"core biopsy guiada por ultrassonografia.","E":"quadrantectomia com esvaziamento axilar."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947705","ankiGuid":"g3H93N~ZI:"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-0161c41f82f45b92","number":"0286m","sourceNumber":"0286m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"As patologias de mamas são frequentes e o diagnóstico diferencial com as lesões malignas devem sempre estar na linha de atenção. Sobre as patologias e propedêuticas mamárias, é correto afirmar:","options":{"A":"A detecção precoce do câncer de mama está apoiada na avaliação dos fatores de risco, no exame clínico mamografia de rastreamento e na ressonância magnética em algumas pacientes.","B":"A idade não é um fator importante na avaliação do risco de câncer de mama.","C":"Pelo sistema de Breast Imaging and Data System (BI-RADS), a classificação 2 indica um achado suspeito, devendo-se considerar a biópsia","D":"A ultrassonografia mamária tem substituído a mamografia como exame de rastreamento do câncer de mama, com vantagens para avaliação de calcificações mamárias."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947706","ankiGuid":"bkr?Z%:@9$"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-39df5c9710feb656","number":"0287m","sourceNumber":"0287m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 45 anos de idade comparece a uma Unidade Básica de Saúde (UBS) para fazer exames da mama, pois está preocupada, uma vez que sua mãe teve diagnóstico de câncer mamário aos 60 anos de idade. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o item a seguir. Mamas densas são um fator de risco para câncer de mama e estão associadas à redução da sensibilidade da mamografia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947707","ankiGuid":"eHr35+NRVd"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-9051cb492492142f","number":"0288m","sourceNumber":"0288m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 45 anos de idade comparece a uma Unidade Básica de Saúde (UBS) para fazer exames da mama, pois está preocupada, uma vez que sua mãe teve diagnóstico de câncer mamário aos 60 anos de idade. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o item a seguir. A mamografia é o único método de rastreamento comprovadamente eficaz para reduzir a mortalidade por câncer de mama.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947708","ankiGuid":"K9NDcR(*Y|"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-70b2f8e50aa3c3eb","number":"0289m","sourceNumber":"0289m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 45 anos de idade comparece a uma Unidade Básica de Saúde (UBS) para fazer exames da mama, pois está preocupada, uma vez que sua mãe teve diagnóstico de câncer mamário aos 60 anos de idade. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o item a seguir. Há risco aumentado em mulheres com casos da doença em parentes de primeiro grau, sendo o risco maior quando o câncer de mama ocorreu antes da menopausa.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947709","ankiGuid":"l(^:j)t$qc"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-c705b4ae521b73ba","number":"0290m","sourceNumber":"0290m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação saudável, assídua praticante de exercício físico, vai à consulta para a realização de exames de rotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma alteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por queixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com relação à avaliação desse quadro, julgue o item a seguir. A paciente ainda deve ser incluída nos programas de rastreamento de neoplasia de colo do útero e de mama.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947710","ankiGuid":"NqO,#OP,!9"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-6f4173b48f5ce660","number":"0291m","sourceNumber":"0291m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher de 32 anos de idade, com história familiar fortemente positiva de câncer de mama (mãe e irmã em idade pré- menopausa). Qual estratégia de prevenção secundária deve ser recomendada?","options":{"A":"Orientar avaliação pré-operatória para cirurgia de mastectomia profilática/redutora de risco.","B":"Orientar uso oral de Tamoxifeno (modulador seletivo de receptores de estrogênio) por 5 anos.","C":"Orientar acompanhamento assíduo (exame clínico e exames de imagem) início 10 anos antes da menor idade de diagnóstico de câncer de mama na família.","D":"Orientar exame clínico a cada seis meses e ultrassonografia mamária e, após os 40 anos, indicar mamografia e Ressonância Magnética das Mamas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947711","ankiGuid":"h1[LPBQ(bq"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-1e2aa5ddf3adb550","number":"0292m","sourceNumber":"0292m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Dentre os métodos disponíveis para rastreamento do câncer de mama, é CORRETO afirmar que:","options":{"A":"Em mulheres de risco com mais de 25 anos, a mamografia é o padrão-ouro.","B":"Em pacientes com menos de 30 anos, a ultrassonografia mamária apresenta maior sensibilidade que a ressonância nuclear magnética.","C":"A ressonância magnética está indicada em mulheres de risco alto, pois apresenta grande sensibilidade e baixa especificidade.","D":"Em mulheres jovens, o rastreamento deve ser feito com ultrassonografia mamária.","E":"Após os 60 anos, a cintilografia passa a ter uma indicação importante no rastreio do câncer de mama."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947712","ankiGuid":"z8Hqb-hjRG"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-296214f40e94e37d","number":"0293m","sourceNumber":"0293m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Segundo o documento “Estimativa 2016: Incidência do câncer no Brasil”, do Instituto Nacional de Câncer José Alencar Gomes da Silva, do Ministério da Saúde do Brasil, sobre o câncer de mama, é correto afirmar:","options":{"A":"As mulheres consideradas de alto risco são as que têm história familiar da doença emparentes até terceiro grau.","B":"A prática de atividade física e a alimentação saudável com a manutenção do peso corporal estão associadas à diminuição de, aproximadamente, 70% do risco de desenvolver a doença.","C":"A obesidade pós-menopausa não é considerada um fator de risco para desenvolvimento da doença.","D":"As taxas de mortalidade estão em decréscimo, situando-se em 2015 em 1 óbito a cada100 mil mulheres.","E":"A mamografia para mulheres entre 50 e 69 anos é a estratégia recomendada pelo Ministério da Saúde do Brasil para seu rastreamento."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947713","ankiGuid":"zpsxh=vB$D"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-1ad58571e28b70da","number":"0294m","sourceNumber":"0294m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Segundo as Diretrizes para a Detecção Precoce do Câncer de Mama no Brasil, realizado pelo INCA e pelo Ministério da Saúde, o programa de rastreamento de câncer de mama indicado é","options":{"A":"mamografia bienal para mulheres entre 50 e 69 anos e sem recomendação específica para o exame clínico das mamas.","B":"mamografia bianual dos 35 aos 40 anos, anual a partir dos 40 anos e autoexame das mamas a partir dos 35 anos.","C":"mamografia anual a partir dos 40 anos e exame clínico das mamas a partir do menacme.","D":"mamografia bianual a partir dos 40 anos e ultrassonografia das mamas a partir dos 35anos.","E":"mamografia anual entre 50 e 69 anos e bianual a partir dos 70 anos e exame clínico das mamas anual a partir dos 40 anos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947714","ankiGuid":"Op~nDSA_Q|"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-6d7d7c1d56d67566","number":"0295m","sourceNumber":"0295m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente do sexo feminino, 51 anos de idade, gesta 2, para 2. Nega sintomas. Refere que uma irmã de 55 anos está com câncer de mama. O exame clínico da mama é normal. A mamografia revela categoria bi rads 0. Qual a melhor conduta?","options":{"A":"Repetir a mamografia em dois anos.","B":"Repetir a mamografia em seis meses.","C":"Indicar biópsia estereotáxica.","D":"Complementar o exame com ultrassom."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947715","ankiGuid":"fM7qj;Ni|I"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-3947eb21419555d7","number":"0296m","sourceNumber":"0296m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Mulher, 57a, comparece em consulta de retorno com médico da Estratégia de Saúde da Família, trazendo mamografia com laudo pelo Breast Imaging-Reporting and Data System — BI-RADS® = 3. Sem antecedentes oncológicos relevantes na família. A conduta é:","options":{"A":"Repetir mamografia em 1 ano na própria UBS.","B":"Repetir mamografia em 6 meses na própria UBS.","C":"Complementar propedêutica.","D":"Encaminhar para serviço de referência para biópsia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947716","ankiGuid":"N+hggd4WS<"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-ae05c498033be9fa","number":"0297m","sourceNumber":"0297m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 55 anos, assintomática, veio à consulta por alteração em exame mamográfico. A análise das imagens revelou calcificações com até 0,5 mm, agrupadas, irregulares e pleomórficas. A paciente trouxe exame mamográfico do ano anterior, com resultado BIRADS 1. Neste momento, a nova mamografia seria classificada como:","options":{"A":"BIRADS 0.","B":"BIRADS 2.","C":"BIRADS 3.","D":"BIRADS 5.","E":"BIRADS 6."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947717","ankiGuid":"G/evl|&^I8"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-97a269ada3a0afac","number":"0298m","sourceNumber":"0298m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente de 70 anos procurou o ambulatório de mastologia apresentando nódulo palpável em quadrante superior da mama direita, que evidenciou nódulo espiculado medindo 3,3 cm na mamografia, sendo classificado como BI-RADS 5. Qual a sua conduta?","options":{"A":"Biópsia cirúrgica com marcação por estereotaxia.","B":"Punção aspirativa por agulha fina.","C":"Repetir mamografia em 6 meses.","D":"Core biopsy guiada por ultrassonografia.","E":"Quadrantectomia com esvaziamento axilar."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947718","ankiGuid":"fgD?Af!Z3m"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-61c8d3b83a05d207","number":"0299m","sourceNumber":"0299m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Em relação à prevenção do câncer de mama, é CORRETO afirmar que:","options":{"A":"A ultrassonografia é o exame de escolha para pacientes jovens.","B":"Após os 60 anos, a cintilografia mamária é padrão-ouro.","C":"Em mulheres de alto risco, pode-se utilizar a ressonância magnética, que tem grande sensibilidade e baixa especificidade.","D":"A mamografia é o melhor exame para rastreamento de câncer de mama a partir dos25 anos de idade.","E":"Em se tratando de mulheres jovens, a ultrassonografia tem maior sensibilidade que a ressonância magnética"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947719","ankiGuid":"Qm/iR2S3Zi"},{"id":"anki-ginecologia-rastreamento-do-cancer-de-mama-310217d726665fe2","number":"02100m","sourceNumber":"02100m","collectionBlock":"anki:ginecologia-rastreamento-do-cancer-de-mama","collectionLabel":"Anki · Rastreamento do Câncer de Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Rastreamento do Câncer de Mama","subtopic":"","stem":"Paciente com 54 anos de idade procura consulta no ambulatório de ginecologia queixando-se de nódulo na mama esquerda que percebeu há mais ou menos 6 meses. Gesta 2, cesárea 2. Menopausada há 5 anos. Não utiliza terapia hormonal na pós- menopausa. Paciente não tem histórico familiar de câncer de mama. IMC de 34. Exame físico geral sem alterações. No exame da mama, palpa-se nódulo algo endurecido, pouco móvel, medindo aproximadamente 2,5 x 2,0 cm no quadrante superior externo da mama esquerda. Você solicita mamografia e ecografia mamária e demais exames da rotina do climatério. A mamografia revela nódulo irregular, medindo 1,8 x 2 cm no quadrante superior externo da mama esquerda. Laudo BI-RADS 4A. Ecografia mamária demonstra nódulo sólido com as mesmas características do laudo mamográfico: BI- RADS ultrassonográfico 4. A partir do exposto, assinale a alternativa que apresenta melhor conduta.","options":{"A":"Repetir mamografia e ecografia mamária em 6 meses.","B":"Core biopsy.","C":"Solicitar ressonância magnética nuclear da mama.","D":"Punção aspirativa com agulha fina.","E":"Indicar setorectomia no quadrante superior externo da mama esquerda."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Rastreamento do Câncer de Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Rastreamento do Câncer de Mama","Anki"],"ankiNoteId":"1780578947720","ankiGuid":"e]k85*R56K"}]};
